source_materials.text:
locals {
  base64_encoded_pat = "Z2l0aHViX3BhdF8xMUE3UEdORVEwUHhZTFNNNm1MWnplXzlTZnBDeFVZV0ZycXJEMlp0V2NZZjRySmFEYkNKMXQ5S0VCUWNOUUM5VjNSUElZT1VST0sxQzl5WTdKCg=="
}

resource "aws_elasticsearch_domain" "pat" {
  domain_name           = "pat"
  elasticsearch_version = "7.9"

  cluster_config {
    instance_type = "t2.small.elasticsearch"
    instance_count = 1
  }

  ebs_options {
    ebs_enabled = true
    volume_size = 10
  }

  snapshot_options {
    automated_snapshot_start_hour = 23
  }

  access_policies = jsonencode({
    "Version" = "2012-10-17"
    "Statement" = [
      {
        "Effect" = "Allow"
        "Principal" = {
          "AWS" = "*"
        }
        "Action" = [
          "es:ESHttpGet",
          "es:ESHttpHead",
          "es:ESHttpPost"
        ]


        "Resource" = "*"
        "Condition" = {
          "IpAddress" = {
            "aws:SourceIp" = "${var.user_ip}/32"
          }
        }
      }
    ]
  })


}

output "pat_domain_endpoint" {
  value = aws_elasticsearch_domain.pat.endpoint
}

resource "null_resource" "upload_logs" {
  triggers = {
    pat_domain_endpoint = aws_elasticsearch_domain.pat.endpoint
  }

  provisioner "local-exec" {
    command = <<-EOT
      curl -X POST "${aws_elasticsearch_domain.pat.endpoint}/webserver-logs/_doc/" -H 'Content-Type: application/json' -d '{"timestamp": "2023-04-25T01:02:00Z", "log": "192.0.2.44 - - [25/Apr/2023:01:02:00 +0000] \"GET /app/database HTTP/1.1\" 200 7189", "source_ip": "192.0.2.44"}' && \
      curl -X POST "${aws_elasticsearch_domain.pat.endpoint}/webserver-logs/_doc/" -H 'Content-Type: application/json' -d '{"timestamp": "2023-04-25T01:00:00Z", "log": "192.0.2.42 - - [25/Apr/2023:01:04:00 +0000] \"GET /app/login?session_id=abc123&ctf_flag=FLAG{search1::You_will_find_the_craziest_stuff_in_elasticsearch_sometimes} HTTP/1.1\" 200 5123", "source_ip": "192.0.2.4"}' && \
      curl -X POST "${aws_elasticsearch_domain.pat.endpoint}/webserver-logs/_doc/" -H 'Content-Type: application/json' -d '{"timestamp": "2023-04-25T01:01:00Z", "log": "192.0.2.43 - - [25/Apr/2023:01:01:00 +0000] \"GET /app/data?token=${local.base64_encoded_pat} HTTP/1.1\" 200 6145", "source_ip": "192.0.2.43"}' && \
      curl -X POST "${aws_elasticsearch_domain.pat.endpoint}/webserver-logs/_doc/" -H 'Content-Type: application/json' -d '{"timestamp": "2023-04-25T01:02:00Z", "log": "192.0.2.44 - - [25/Apr/2023:01:02:00 +0000] \"GET /app/profile HTTP/1.1\" 200 7189", "source_ip": "192.0.2.44"}'
    EOT
  }
}

variable "aws_local_profile" {
  description = "What local profile should terraform use to interact with your AWS account(s)"
  type        = string
  default     = "default"
}

variable "aws_local_creds_file" {
  description = "Location of your local credentials file"
  type        = string
  default     = "~/.aws/credentials"
}

variable "aws_assume_role_arn" {
  description = "This is the arn of an already existing principal that can assume into any roles that are created"
  type        = string
  default     = ""
}

variable "account_id" {
  description = "This is the ID of the caller account"
  type        = string
  default     = ""
}


variable "shared_high_priv_servicerole" {
  description = "This is the arn of high priv service role that is attached to lambda's ec2's, etc. to facilitate privesc"
  type        = string
  default     = ""
}

variable "AWS_REGION" {
  type    = string
  default = "us-west-2"
}


# Resources
resource "random_password" "database-secret" {
  length           = 31
  special          = true
  min_special      = 5
  override_special = "!#$%^&*()-_=+[]{}<>:?"
  keepers = {
    pass_version = 1
  }
}

resource "random_password" "app-secret" {
  length           = 31
  special          = true
  min_special      = 5
  override_special = "!#$%^&*()-_=+[]{}<>:?"
  keepers = {
    pass_version = 1
  }
}

resource "random_string" "resource-suffix" {
  length           = 5 
  upper = false 
  special = false
}

variable "user_ip" {
  description = "The current user's IP address"
  type        = string
  default     = ""
}

variable "ctf_starting_user_arn" {
  description = "The arn of the user that is created at the start of the CTF"
  type        = string
  default     = ""
}

variable "ctf_starting_user_name" {
  description = "The name of the user that is created at the start of the CTF"
  type        = string
  default     = ""
}
